def do_algebra(operators, operands):
    # Start with the first operand
    result = operands[0]

    # Iterate over the operators and corresponding operands
    for i, op in enumerate(operators):
        if op == '+':
            result += operands[i + 1]
        elif op == '-':
            result -= operands[i + 1]
        elif op == '*':
            result *= operands[i + 1]
        elif op == '//':
            result //= operands[i + 1]
        elif op == '**':
            result **= operands[i + 1]
        else:
            raise ValueError(f"Unsupported operator: {op}")

    return result

